head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/pre_newlisting.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/listing_iss_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/json2.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/report.js");
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vBzProcsNo = "";
scwin.pBzProcsNo = "";
scwin.gPrtdepoSeq;
scwin.vSecugrpID, scwin.vSPOT_ISU_TRD_MKT_TP_CD;
scwin.vPageTYp;
scwin.TR_JOB;
scwin.gAcptNo;
scwin.gAcptSeq;
scwin.visuShrsLabelNm = "주식";
scwin.vIsuDtlRowPosition = "";
scwin.gAcptNoListFee;

// 유가보호예수땜시추가
scwin.gPrtdepoCount;
scwin.chkPrtdepoCond = true;
scwin.formCd = "";
scwin.vScrenID = "ULDSTF92002.xml";
//스톡옵션 의무보유땜시 추가
scwin.vStkOptIsurCd, scwin.vStkOptComNm = "";
scwin.onpageload = function() {

};
scwin.onpageunload = function() {
};
scwin.setObjectState = function() {
    //alert('vSPOT_ISU_TRD_MKT_TP_CD]'+vSPOT_ISU_TRD_MKT_TP_CD);
    $c.stf.showObj(panel_Discls_Viewer, false);
    if (js_market == '9') {
        $c.stf.showObj(panel_Discls_Viewer, true);
    }
    if (scwin.vSPOT_ISU_TRD_MKT_TP_CD == '1') {
        $c.stf.showObj(panel_KSE, true); //심볼
        $c.stf.showObj(panel_STKCERT_MIX, true); //혼용유통기간
        $c.stf.showObj(panel_Print, true); //2014.12.3 인쇄 가능으로 요청
        $c.stf.showObj(panel_BACKLIST_YN, false);
        $c.stf.showObj(panel_KOSDAQ, false);
        $c.stf.showObj(panel_PAIDCAPINC_ISU_TP_CD, false);
        $c.cm.setColumnProp(grd_IsuDtl, "CORPBND_ISU_RND", "Show", false);

        //유가의 경우 상장 수수료에 관한 내용이 나오지 않는다.
        $c.stf.showObj(btn_send, false);
        $c.stf.showObj(pan_listFee_cos, false);
    } else if (scwin.vSPOT_ISU_TRD_MKT_TP_CD == '2' || scwin.vSPOT_ISU_TRD_MKT_TP_CD == "6") {
        $c.stf.showObj(panel_KSE, false);
        $c.stf.showObj(panel_STKCERT_MIX, false); //혼용유통기간
        $c.stf.showObj(panel_Print, true);
        $c.stf.showObj(panel_BACKLIST_YN, true);
        $c.stf.showObj(panel_KOSDAQ, true);
        $c.stf.showObj(panel_PAIDCAPINC_ISU_TP_CD, true);
        $c.cm.setColumnProp(grd_IsuDtl, "CORPBND_ISU_RND", "Show", true);

        //코스닥의 경우 접수번호가 없으면 상장수수료를 발송할 수 없다.
        if (scwin.gAcptNoListFee == "") {
            $c.stf.showObj(pan_listFee_cos, false);
            $c.stf.showObj(btn_send, false);
        } else {
            $c.stf.showObj(pan_listFee_cos, true);
            $c.stf.showObj(btn_send, true);
            scwin.fn_listFee();
        }
    }
    if (scwin.vSecugrpID == SECUGRP_ID_DR) {
        $c.stf.showObj(panel_PARVAL, false);
        $c.stf.showObj(panel_ISU_CAP, false);
        scwin.visuShrsLabelNm = "DR";
        $c.stf.setObjectValue(lb_ISU_SHRS, "증감" + scwin.visuShrsLabelNm + "수");
        $c.stf.setObjectValue(lb_BF_ACC_ISU_SHRS, "변경전 상장" + scwin.visuShrsLabelNm + "수");
        $c.stf.setObjectValue(lb_ACC_ISU_SHRS, "상장DR수");
        $c.stf.setObjectValue(lb_INDVDL_INCDEC_LIST_SHRS, "개별증감" + scwin.visuShrsLabelNm + "수");
        edt_PARVAL.MaxDecimalPlace = 3;
    } else {
        $c.stf.showObj(panel_PARVAL, true);
        $c.stf.showObj(panel_ISU_CAP, true);
        scwin.visuShrsLabelNm = "주식";
        edt_PARVAL.MaxDecimalPlace = 0;
    }
    if (scwin.vSecugrpID == SECUGRP_ID_FS) {
        edt_PARVAL.MaxDecimalPlace = 3;
    }
    if (scwin.vSecugrpID == SECUGRP_ID_DR || scwin.vSecugrpID == SECUGRP_ID_FS) {
        $c.stf.showObj(panel_CURR_ISO_CD, true);
        $c.stf.showObj(txb_CURR_ISO_NM_1, true);
        $c.stf.showObj(txb_CURR_ISO_NM_2, true);
        $c.stf.showObj(txb_CURR_ISO_NM_3, true);
        $c.stf.showObj(txb_CURR_ISO_NM_4, true);
    } else {
        $c.stf.showObj(panel_CURR_ISO_CD, false);
        $c.stf.showObj(txb_CURR_ISO_NM_1, false);
        $c.stf.showObj(txb_CURR_ISO_NM_2, false);
        $c.stf.showObj(txb_CURR_ISO_NM_3, false);
        $c.stf.showObj(txb_CURR_ISO_NM_4, false);
    }
};
scwin.resizeToWin = function() {
    $c.stf.MoveCenterOfParent();
};
scwin.fn_searchCode = function() {
    /*
    01873 - 유상증자발행구분코드
    00443 - 통화표시
    */
    var arrCid = [{
        cid: "PAIDCAPINC_ISU_TP_CD",
        cnm: "cmb_PAIDCAPINC_ISU_TP_CD"
    }, {
        cid: "CURR_ISO_CD",
        cnm: "cmb_CURR_ISO_CD"
    }];
    var objCod;
    var url = "/CodeAction.do?method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='PAIDCAPINC_ISU_TP_CD','CURR_ISO_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    for (var i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        //alert('[objCod]'+objCod);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        if (arrCid[i].cid == 'PAIDCAPINC_ISU_TP_CD') {
            strCbd = "^' '";
        }
        for (var j = 1; j <= dts_Cod.getTotalRow(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};
scwin.fn_initForm = function(initTyp) {
    if (initTyp == 'I') {
        img_ISU_CD.src = "../img/btn_search.gif";
        img_ISU_CD.setDisabled(false);
    } else if (initTyp == 'X') {
        img_ISU_CD.src = "../img/btn_search_d.gif";
        img_ISU_CD.setDisabled(true);
    }
};
scwin.fn_SetComboCode = function() {
    var url = "/CodeAction.do?method=listStkIsuRsnCd&inputMessageId=STK_ISU_RSN_CD_OUT";
    url += "&LD_MKT_TP_CD=" + scwin.vSPOT_ISU_TRD_MKT_TP_CD;
    //발행사유코드
    dts_STK_ISU_RSN_CD.DataID = encodeURI(url);
    dts_STK_ISU_RSN_CD.Reset();
};
scwin.fn_GetParIsuCd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = scwin.vSecugrpID;
    arrPar[1] = $c.stf.getObjectValue(txb_ISUR_CD); // 코드값을 포함할 컨트롤
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParIsuCd = function(arrPar) {
    //var dbClickYn =  arrPar[0].DBCLICKYN;
    if (arrPar[0].ISU_CD != "") {
        txb_ISU_CD.setValue(arrPar[0].ISU_CD);
        txb_ISU_KOR_NM.setValue(arrPar[0].ISU_KOR_NM);
        txb_ISU_KOR_ABBRV.setValue(arrPar[0].ISU_KOR_ABBRV);
        txb_ISU_ENG_NM.setValue(arrPar[0].ISU_ENG_NM);
        txb_ISU_ENG_ABBRV.setValue(arrPar[0].ISU_ENG_ABBRV);
        txb_ISU_SRT_CD.setValue(arrPar[0].ISU_SRT_CD);
        txb_ISU_ENG_SYMBL.setValue(arrPar[0].ISU_ENG_SYMBL);
        $c.stf.setObjectValue(cmb_CURR_ISO_CD, arrPar[0].CURR_ISO_CD);
        if (scwin.vSecugrpID == SECUGRP_ID_DR) {
            $c.stf.setObjectValue(cmb_STKCERT_KIND_CD, 'KDR'); //주식의종류코드를 셋팅

        } else if (scwin.vSecugrpID == SECUGRP_ID_FS) {
            $c.stf.setObjectValue(cmb_STKCERT_KIND_CD, '000'); //주식의종류코드를 셋팅

        } else {
            $c.stf.setObjectValue(cmb_STKCERT_KIND_CD, $c.stf.getObjectValue(txb_ISU_CD).substring(8, 11)); //주식의종류코드를 셋팅

        }
        scwin.fn_setPREFSTKEvent();
        scwin.fn_nprefstk_read_sync(txb_ISU_CD.getValue());
        scwin.fn_bf_read_sync();
    }
};



/**
 * 변경전 주식수, 자본금 가져오기
 */
scwin.fn_bf_read_sync = function() {
    $c.lic.fn_bf_read_sync2(dts_BfData, txb_ISU_CD, edt_BF_ACC_ISU_SHRS, edt_BF_ACC_ISU_CAP);
};
scwin.fn_setPREFSTKEvent = function() {
    if (scwin.vSecugrpID == SECUGRP_ID_ST) {
        if ($c.stf.getObjectValue(cmb_STKCERT_KIND_CD) == '000' || $c.stf.getObjectValue(cmb_STKCERT_KIND_CD).substring(0, 1) == 'K') {
            scwin.fn_setPREFSTKItem(false);
        } else {
            scwin.fn_setPREFSTKItem(true);
        }
    } else {
        scwin.fn_setPREFSTKItem(false);
    }
};
scwin.fn_setPanelPREFSTK = function(isTrue) {
    $c.stf.showObj(panel_PREFSTK, isTrue);
};
scwin.fn_setNPARVALSTK = function(isTrue) {
    $c.stf.showObj(panel_NPARVALSTK, isTrue);
};
scwin.fn_setPREFSTKItem = function(isTrue) {
    $c.stf.showObj(chk_PREFSTK_TP_CD, isTrue);
    $c.stf.showObj(label_PREFSTK_TP_CD, isTrue);
};
scwin.fn_nprefstk_read_sync = function(isucd) {
    var url = "/Listing.do?method=searchIsuIssChgList" + "&DIV_IDX=" + DIV_IDX_ISS_NEWPREFSTK_STK_HIST + "&TRS_IDX=" + TRS_IDX_NEWSEL + "&ISU_CD=" + isucd;
    dts_NEWPREFSTK.DataID = encodeURI(url);
    dts_NEWPREFSTK.Reset();
    if (dts_NEWPREFSTK.getTotalRow() > 0) {
        dts_Isu.setCellData(1, "PREFSTK_ISU_DD", dts_NEWPREFSTK.getCellData(1, "ISU_DD"));
        dts_Isu.setCellData(1, "PREFSTK_DIV_RT", dts_NEWPREFSTK.getCellData(1, "PREFSTK_DIV_RT"));
        dts_Isu.setCellData(1, "PREFSTK_CONTIN_DEADLINE_YYS", dts_NEWPREFSTK.getCellData(1, "PREFSTK_CONTIN_DEADLINE_YYS"));
        dts_Isu.setCellData(1, "PREFSTK_CONTIN_DEADLINE_MM", dts_NEWPREFSTK.getCellData(1, "PREFSTK_CONTIN_DEADLINE_MM"));
        dts_Isu.setCellData(1, "PREFSTK_CONTIN_DEADLINE_DYS", dts_NEWPREFSTK.getCellData(1, "PREFSTK_CONTIN_DEADLINE_DYS"));
        dts_Isu.setCellData(1, "PREFSTK_END_DD", dts_NEWPREFSTK.getCellData(1, "PREFSTK_END_DD"));
        scwin.fn_setNprefCheckBox(dts_NEWPREFSTK);
        dts_Isu.setCellData(1, "NEWPREFSTK_REMK", dts_NEWPREFSTK.getCellData(1, "NEWPREFSTK_REMK"));
        chk_PREFSTK_TP_CD.setValue(1);
        scwin.fn_setPREFSTKItem(true);
        scwin.fn_setPanelPREFSTK(true);
        //alert(dts_NEWPREFSTK.Text);

    } else {
        dts_Isu.setCellData(1, "PREFSTK_ISU_DD", '');
        dts_Isu.setCellData(1, "PREFSTK_DIV_RT", '');
        dts_Isu.setCellData(1, "PREFSTK_CONTIN_DEADLINE_YYS", '');
        dts_Isu.setCellData(1, "PREFSTK_CONTIN_DEADLINE_MM", '');
        dts_Isu.setCellData(1, "PREFSTK_CONTIN_DEADLINE_DYS", '');
        dts_Isu.setCellData(1, "PREFSTK_END_DD", '');
        dts_Isu.setCellData(1, "INDEFINPD_YN", '');
        dts_Isu.setCellData(1, "PARTCTP_YN", '');
        dts_Isu.setCellData(1, "ACCTP_YN", '');
        dts_Isu.setCellData(1, "NDIVTM_VOTERGHT_YN", '');
        dts_Isu.setCellData(1, "NEWPREFSTK_REMK", '');
        chk_PREFSTK_TP_CD.setValue(0);
        scwin.fn_setPanelPREFSTK(false);
        scwin.fn_setPREFSTKEvent();
        //dts_NEWPREFSTK.DeleteRow(1);

    }
};
scwin.fn_setCheckboxData = function(obj, val) {
    if (val == 'Y') {
        obj.setValue(1);
    } else {
        obj.setValue(0);
    }
};
scwin.fn_getCheckboxData = function(obj) {
    if (obj.checked) {
        return 'Y';
    } else {
        return 'N';
    }
};
scwin.fn_extr_read_sync = function() {
    var url = "/Listing.do?method=searchIsuIssChgList" + "&DIV_IDX=" + DIV_IDX_ISS_STK_RECV + "&TRS_IDX=" + TRS_IDX_NEWSEL + "&ACPT_NO=" + scwin.gAcptNo + "&BYACPTNO_SEQ=" + scwin.gAcptSeq;
    dts_Isu.DataID = encodeURI(url);
    dts_Isu.Reset();
    if (dts_Isu.getCellData(1, "NPARVALSTK_YN") == 'Y') {
        chk_NPARVALSTK_YN.setValue(1);
    }
    scwin.fn_setNPARVALSTK_YNEvent();
    url = "/Listing.do?method=searchIsuIssChgList" + "&DIV_IDX=" + DIV_IDX_ISS_DTL_STK_RECV + "&ACPT_NO=" + scwin.gAcptNo;
    dts_IsuDtl.DataID = encodeURI(url);
    dts_IsuDtl.Reset();
    url = "/Listing.do?method=searchIsuIssChgList" + "&DIV_IDX=" + DIV_IDX_ISS_PRTDEPO_STK_RECV + "&ACPT_NO=" + scwin.gAcptNo;
    dts_PRTDEPO.DataID = encodeURI(url);
    dts_PRTDEPO.Reset();
    url = "/Listing.do?method=searchIsuIssChgList" + "&DIV_IDX=" + DIV_IDX_ISS_STK_RECV + "&TRS_IDX=" + TRS_IDX_NEWSEL2 + "&ACPT_NO=" + scwin.gAcptNo;
    dts_DoubleChk.DataID = encodeURI(url);
    dts_DoubleChk.Reset();
    var modDocCnt = dts_DoubleChk.getCellData(1, "CNT");
    if (modDocCnt > 0) {
        $c.win.alert("◆  처리방법 안내  ◆\n\r\n\r" + "선택내용은 [정정]신청건으로 이전신청서가 처리되어 주식발행내역에 존재합니다.\n\r\n\r" + "상장주식수와 상장자본금이 중복계산되오니 다음의 방법으로 처리바랍니다.\n\r\n\r\n\r" + "case 1. 이전신청서가 공시가 됐을경우 \n\r\n\r" + "     정정신청건 삭제([신청종목삭제] 버튼) -> 주식발행내역에서 이전처리건을 선택하여 정정내용을 수정 -> 정정공시문 작성 \n\r\n\r\n\r" + "caer 2. 이전신청서가 미공시  됐을경우 \n\r\n\r" + "     주식발행내역에서 이전처리건을 선택하여 삭제 -> 정정신청건 저장 -> 공시문 작성\n\r");
    }
};
scwin.fn_read_sync = function() {
    var url = "/Listing.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=searchIsuIssChgList" + "&DIV_IDX=" + DIV_IDX_ISS_STK_HIST + "&TRS_IDX=" + TRS_IDX_NEWSEL + "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    dts_Isu.DataID = encodeURI(url);
    dts_Isu.Reset();
    if (dts_Isu.getCellData(1, "PREFSTK_TP_CD") == '2') {
        chk_PREFSTK_TP_CD.setValue(1);
        scwin.fn_setPREFSTKItem(true);
        scwin.fn_setPanelPREFSTK(true);
    } else {
        scwin.fn_setPREFSTKEvent();
    }
    if (dts_Isu.getCellData(1, "NPARVALSTK_YN") == 'Y') {
        chk_NPARVALSTK_YN.setValue(1);
    }
    scwin.fn_setNPARVALSTK_YNEvent();
    txb_CURR_ISO_NM_1.setValue("(" + dts_Isu.getCellData(1, "CURR_ISO_CD") + ")");
    txb_CURR_ISO_NM_2.setValue("(" + dts_Isu.getCellData(1, "CURR_ISO_CD") + ")");
    txb_CURR_ISO_NM_3.setValue("(" + dts_Isu.getCellData(1, "CURR_ISO_CD") + ")");
    txb_CURR_ISO_NM_4.setValue("(" + dts_Isu.getCellData(1, "CURR_ISO_CD") + ")");
    scwin.fn_setNprefCheckBox(dts_Isu);
    scwin.fn_setCheckboxData(chk_NEWSTK_REL_LAWST_YN, dts_Isu.getCellData(1, "NEWSTK_REL_LAWST_YN"));
    scwin.fn_setCheckboxData(chk_BACKLIST_YN, dts_Isu.getCellData(1, "BACKLIST_YN"));
    url = "/Listing.do?method=searchIsuIssChgList" + "&DIV_IDX=" + DIV_IDX_ISS_DTL_STK_HIST + "&TRS_IDX=" + TRS_IDX_NEWSEL + "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    dts_IsuDtl.DataID = encodeURI(url);
    dts_IsuDtl.Reset();

    // 보호예수로추가
    if (js_market == '1') {
        //fn_prtdepo_read_sync_STK_setHeader();
        scwin.fn_prtdepo_read_sync();
    } else {
        scwin.fn_prtdepo_read_sync();
    }
};
scwin.fn_prtdepo_read_sync = function() {
    var url = "/Listing.do?method=searchIsuIssChgList" + "&DIV_IDX=" + DIV_IDX_ISS_PRTDEPO_STK_HIST + "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    dts_PRTDEPO.DataID = encodeURI(url);
    dts_PRTDEPO.Reset();
};
scwin.fn_prtdepo_read_sync_STK = function() {
    var url = "/listingCommon.do?method=listGeneral" + "&outputMessageId=STKCERT_ISU_PRTDEPO_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.lstlst.select.stk.appl.prtdepo.list.condition" + "&{P}param01=" + $c.stf.getObjectValue(txb_ISUR_CD) + "&{P}param02=" + $c.stf.getObjectValue(edt_LIST_DD);
    dts_PRTDEPO.DataID = encodeURI(url);
    dts_PRTDEPO.Reset();
    //ShowWin(dts_PRTDEPO);
    scwin.gPrtdepoCount = dts_PRTDEPO.getTotalRow();
};


