scwin.fn_CheckForm = function() {
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    if ($c.stf.getObjectValue(txb_ISUR_CD) == "") {
        $c.win.alert("[회사코드] 항목값이  없습니다.");
        txb_ISUR_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_LIST_METHD_TP_CD) == "") {
        $c.win.alert("[상장방식]을 선택하세요.");
        cmb_LIST_METHD_TP_CD.focus();
        return false;
    }
    var vListMthTpCd = $c.stf.getObjectValue(cmb_LIST_METHD_TP_CD);
    if (scwin.vPageTYp == '1') {
        if (vListMthTpCd != LIST_METHD_TP_CD_2) {
            //alert("이화면에서는  상장방식을 [신주상장, 추가상장]만 선택할 수 있습니다.");cmb_LIST_METHD_TP_CD.focus();return false;
            $c.win.alert("이화면에서는  상장방식을 [추가상장]만 선택할 수 있습니다.");
            cmb_LIST_METHD_TP_CD.focus();
            return false;
        }
    } else if (scwin.vPageTYp == '2') {
        if (vListMthTpCd != LIST_METHD_TP_CD_3) {
            $c.win.alert("이화면에서는  상장방식을 [변경상장]만 선택할 수 있습니다.");
            cmb_LIST_METHD_TP_CD.focus();
            return false;
        }
    }
    if ($c.stf.getObjectValue(txb_ISU_CD) == "") {
        $c.win.alert("[종목]을 선택하세요.");
        img_ISU_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_LIST_METHD_TP_CD) == LIST_METHD_TP_CD_1) {
        var dbchkCnt = -1;
        dbchkCnt = scwin.fn_check_double_listed();
        if (dbchkCnt > 0) {
            $c.win.alert("선택종목은 이미상장된 종목입니다. 확인후 다시 조치바랍니다.");
            return false;
        }
    }
    if ($c.stf.getObjectValue(cmb_LIST_METHD_TP_CD) == LIST_METHD_TP_CD_1) {
        if ($c.stf.getObjectValue(txb_ISU_SRT_CD) == "") {
            $c.win.alert("[종목단축코드]항목값이  없습니다."); //txb_ISU_SRT_CD.focus();return false;

        }
        if ($c.stf.getObjectValue(txb_ISU_KOR_NM) == "") {
            $c.win.alert("[한글종목명]을 입력하세요.");
            txb_ISU_KOR_NM.focus();
            return false;
        }
        if ($c.stf.getObjectValue(txb_ISU_KOR_ABBRV) == "") {
            $c.win.alert("[한글종목약명]을 입력하세요.");
            txb_ISU_KOR_ABBRV.focus();
            return false;
        }
        if ($c.stf.getObjectValue(txb_ISU_ENG_NM) == "") {
            $c.win.alert("[영문종목명]을 입력하세요.");
            txb_ISU_ENG_NM.focus();
            return false;
        }
        if ($c.stf.getObjectValue(txb_ISU_ENG_ABBRV) == "") {
            $c.win.alert("[영문종목약명]을 입력하세요.");
            txb_ISU_ENG_ABBRV.focus();
            return false;
        }
        if (scwin.vSPOT_ISU_TRD_MKT_TP_CD == "1") {
            if ($c.stf.getObjectValue(txb_ISU_ENG_SYMBL) == "") {
                $c.win.alert("[영문종목심볼]을 입력하세요.");
                txb_ISU_ENG_SYMBL.focus();
                return false;
            }
            if ($c.lc.fn_eng_symbl_check($c.stf.getObjectValue(txb_ISU_ENG_SYMBL))) {
                if (!$c.lc.fn_chkCorpSymblDoubleInput($c.stf.getObjectValue(txb_ISU_ENG_SYMBL), $c.stf.getObjectValue(txb_ISUR_CD), dts_Symbl)) {
                    $c.win.alert(MSG_SYMBL_DOUBLE_INPUT);
                    return false;
                }
            } else {
                txb_ISU_ENG_SYMBL.focus();
                return false;
            }
        }
    }
    if ($c.stf.getObjectValue(cmb_LIST_METHD_TP_CD) == LIST_METHD_TP_CD_2) {
        //추가상장
        if ($c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) == "609" || $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) == "626" || $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) == "627" ||
            $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) == "640" || $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) == "641" || $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) == "643" ||
            $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) == "632" || $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) == "633" || $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) == "648" ||
            $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) == "649") {
            $c.win.alert("[추가상장]에 해당하는 주식발행사유가 아닙니다. 주식발행사유를 확인하시기 바랍니다.");
            cmb_STK_ISU_RSN_CD.focus();
            return;
        }
    }
    if ($c.stf.getObjectValue(cmb_LIST_METHD_TP_CD) == LIST_METHD_TP_CD_3) {
        //변경상장	
        if ($c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) == "602" || $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) == "644" || $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) == "608" ||
            $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) == "611" || $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) == "614" || $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) == "617" ||
            $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) == "618" || $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) == "619" || $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) == "620" ||
            $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) == "621" || $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) == "622" || $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) == "623" ||
            $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) == "624" || $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) == "630" || $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) == "631" ||
            $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) == "642") {
            $c.win.alert("[변경상장]에 해당하는 주식발행사유가 아닙니다. 주식발행사유를 확인하시기 바랍니다.");
            cmb_STK_ISU_RSN_CD.focus();
            return;
        }
    }

    //2009.04.07 변경상장일경우는 상장일을 입력안해도 되도록 변경함.
    if (scwin.vPageTYp == '2') {
        //코스닥 일때만 주식발행사유 600번대
        if ($c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) >= 600 && $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) != "625") {
            //상장일이 없으면 '-' 으로 대체
            if ($c.stf.getObjectValue(edt_LIST_DD) == "") {
                dts_Isu.setCellData(1, "LIST_DD", '-');
                $c.win.alert("변경상장일 경우 상장일 입력을 안하시면 '-' 으로 처리됩니다.");
            }
        } else {
            if ($c.stf.getObjectValue(edt_LIST_DD) == "") {
                $c.win.alert("[상장일]을 입력하세요.");
                edt_LIST_DD.focus();
                return false;
            }
        }
    } else {
        if ($c.stf.getObjectValue(edt_LIST_DD) == "") {
            $c.win.alert("[상장일]을 입력하세요.");
            edt_LIST_DD.focus();
            return false;
        }
        if (vCurDate >= $c.stf.getObjectValue(edt_LIST_DD)) {
            $c.win.alert("[상장일]을 현재일이후로 입력하세요.");
            edt_LIST_DD.focus();
            return false;
        }
    }
    if ($c.stf.getObjectValue(cmb_LIST_METHD_TP_CD) == LIST_METHD_TP_CD_3) {
        //20081017 코스닥이고 이익소각이면 발행일자 입력이 필수가 아니도록 변경
        //20100514 코스닥이고 감자(유상)일 경우 발행일자와 발행회차 입력이 필수가 아니도록 변경
        //626 : 이익소각, 609 : 감자(유상)
        //699 : 기타 추가 20100809(강진희)
        //650:주식소각
        //625:우선주의 보통주전환  추가(2017.05.15)

        if ($c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) == "626" || $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) == "609" || $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) == "650" || $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) == "625" ||
            $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) == "699") {

        } else {
            if ($c.stf.getObjectValue(edt_ISU_DD) == "") {
                $c.win.alert("[발행일]을 입력하세요.");
                edt_ISU_DD.focus();
                return false;
            }
            if ($c.stf.getObjectValue(edt_ISU_RND) == "") {
                $c.win.alert("[발행회차]를 입력하세요.");
                edt_ISU_RND.focus();
                return false;
            }
        }
        if ($c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) == "625") {
            if (!scwin.fn_checkIsuDtlDtl(dts_IsuDtl)) return false;
        }
    }
    if ($c.stf.getObjectValue(cmb_STKCERT_KIND_CD) == "") {
        $c.win.alert("[주식의종류]를 선택하세요.");
        cmb_STKCERT_KIND_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) == "") {
        $c.win.alert("[주식발행사유]를 선택하세요.");
        cmb_STK_ISU_RSN_CD.focus();
        return false;
    }
    var isuRsnCd = $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD);
    if (isuRsnCd == '115') {
        $c.win.alert("주식발행사유로 [상장폐지(종목별)]을 선택할수 없습니다.");
        cmb_STK_ISU_RSN_CD.focus();
        return false;
    }
    //신규상장시 선택하는 발행사유들...
    if (isuRsnCd == '198') {
        $c.win.alert("주식발행사유로 [설립]을 선택할수 없습니다.");
        cmb_STK_ISU_RSN_CD.focus();
