        if ($c.stf.getObjectValue(edt_ISU_SHRS) !== "0") {
            $c.stf.setObjectValue(edt_ISU_SHRS, 0);
            $c.win.alert("주식발행사유가 [상호변경]시에는 [증감" + scwin.visuShrsLabelNm + "수]을 '0'으로 자동설정합니다.");
        }
    }

    ///*
    if (scwin.vSecugrpID != SECUGRP_ID_MF && scwin.vSecugrpID != SECUGRP_ID_IF && scwin.vSecugrpID != SECUGRP_ID_DR) {
        if ($c.stf.getObjectValue(chk_NPARVALSTK_YN) != "Y" && $c.stf.getObjectValue(edt_PARVAL) == "0") {
