            $c.win.alert("[주당자본금]을 입력하세요.");
            edt_PER1STK_CAP.focus();
            return false;
        }
        if (isuRsnCd != '643' && isuRsnCd != '160' && //상호변경
            $c.stf.getObjectValue(chk_NPARVALSTK_YN) != "Y") {
            //무액면주식 여부
            if (!scwin.fn_checkZeroNumber(edt_PARVAL, "액면가")) return false;
        }
    }
    if (isuRsnCd == '640' || isuRsnCd == '170' || // 액면병합
        isuRsnCd == '641' || isuRsnCd == '171') {
        // 액면분할

        var dbchkCnt = -1;
        dbchkCnt = scwin.fn_check_parval_input();
        if ($c.stf.getObjectValue(chk_NPARVALSTK_YN) != "Y" && dbchkCnt == 1) {
            $c.win.alert("주식발행사유가 [액면병합, 분할]인데 원부의 액면가와 동일하게 입력하셨습니다.");
            return false;
        }
    } else {
        if ($c.stf.getObjectValue(cmb_LIST_METHD_TP_CD) != LIST_METHD_TP_CD_1) {
            var dbchkCnt = -1;
            dbchkCnt = scwin.fn_check_parval_input();
            if ($c.stf.getObjectValue(chk_NPARVALSTK_YN) != "Y" && dbchkCnt == 0) {
                $c.win.alert("주식발행사유가 [액면병합, 분할] 일때만 액면가를 변경 입력 할 수 있습니다. ");
                return false;
            }
        }
    }

    //if (! fn_checkNumber(edt_PARVAL, '액면가')) return false;

    if (scwin.vSPOT_ISU_TRD_MKT_TP_CD == '2' && vListMthTpCd != LIST_METHD_TP_CD_3) {
        //코스닥이면 변경상장이면 발행가액이 없음, 추가상장일때도 없는경우가 있어 주석처리함 2009.02.03.

        //if (getObjectValue(edt_ISU_PRC) == "") {

        //	alert("[발행가]을 입력하세요.");edt_ISU_PRC.focus();return false;

        //}

