scwin.fn_getListBzTpCd = function() {
    var str = "";
    if ($c.stf.getObjectValue(cmb_LIST_METHD_TP_CD) == LIST_METHD_TP_CD_1) {
        str = LIST_BZ_TP_CD_120; //신주상장

    } else if ($c.stf.getObjectValue(cmb_LIST_METHD_TP_CD) == LIST_METHD_TP_CD_2) {
        str = LIST_BZ_TP_CD_130; //추가상장

    } else if ($c.stf.getObjectValue(cmb_LIST_METHD_TP_CD) == LIST_METHD_TP_CD_3) {
        str = LIST_BZ_TP_CD_141; //변경상장

    }
    return str;
};
scwin.fn_getCheckboxNprefStk = function(obj, stk_knd) {
    var val;
    if (obj.checked) {
        val = '2';
    } else {
        if (stk_knd == "000" || stk_knd == "KDR") {
            val = '0';
        } else {
            val = '1';
        }
    }
    return val;
};
