// 보호예수수정건수가있냐?
scwin.fn_chkPrtdepoCond_03 = function() {
    //var gPrtdepoCount = dts_PRTDEPO.CountRow;
    //alert("gPrtdepoCount="+gPrtdepoCount);
    var gStat;
    var gStatCnt = 0;
    for (var k = 1; k <= dts_PRTDEPO.getTotalRow(); k++) {
        gStat = dts_PRTDEPO.getRowStatus(k);
        //if (gStat == TB_JOB_UPDATE) {
        if (gStat == TB_JOB_NORMAL) {
            gStatCnt++;
        }
    }

    //alert("gStatCnt="+gStatCnt);
    if (scwin.gPrtdepoCount == gStatCnt) {
        return true;
    } else {
        return false;
    }
};
scwin.fn_save = function() {
    scwin.TR_JOB = 'I';
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        scwin.vBzProcsNo = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);
        if (scwin.vBzProcsNo.length != 14) {
            $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            dts_Isu.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);

            /*
            alert(
            	"test vBzProcsNo="+vBzProcsNo+"\n"+
            	"fn_chkPrtdepoCond_00="+fn_chkPrtdepoCond_00()+"\n"+
            	"fn_chkPrtdepoCond_01="+fn_chkPrtdepoCond_01()+"\n"+
            	"fn_chkPrtdepoCond_02="+fn_chkPrtdepoCond_02()+"\n"+
            	"fn_chkPrtdepoCond_03="+fn_chkPrtdepoCond_03()+"\n"+

            	"fn_chkPrtdepoCond_02 count="+dts_PRTDEPO.CountRow

            );
            */

            if ((js_market == '1') &&
                scwin.fn_chkPrtdepoCond_00() && scwin.fn_chkPrtdepoCond_01()) {
                //alert("test vBzProcsNo="+fn_chkPrtdepoCond_00() + fn_chkPrtdepoCond_01());

                if (scwin.chkPrtdepoCond) {
                    scwin.fn_prtdepo_read_sync_STK_count();
                }
            }
            if ((js_market == '1') &&
                scwin.fn_chkPrtdepoCond_00() && scwin.fn_chkPrtdepoCond_01() && scwin.fn_chkPrtdepoCond_02() &&
                (scwin.gPrtdepoCount > 0) &&
                scwin.chkPrtdepoCond) {
                $c.win.alert("               【의무보유 시장조치 안내】\n해당 종목에 의무보유중인 증권이 있습니다.\n의무보유내역에서 의무보유수량을 정정조치하여 주시기 바랍니다.");
                scwin.fn_prtdepo_read_sync_STK();
                scwin.chkPrtdepoCond = false;
                scwin.formCd = "68155";
                return;
            }
            if ((js_market == '1') &&
                scwin.fn_chkPrtdepoCond_00() && scwin.fn_chkPrtdepoCond_03()) {
                var msg = "변경상장사유가 의무보유정보 수정대상이나 수정조치가 이루어지지 않았습니다.\n다시 한번 수정여부를 확인하여 주십시오.\n수정없이 그대로 진행하기를 원하시면 확인을 누르십시오.";
                var res = window.confirm(msg);
                if (!res) {
                    return;
                }
            }
            scwin.fn_trs(TRS_IDX_INSERT);
        }
    }
};
