scwin.fn_trs = function(trsIdx) {
    //dts_Isu.NameValue(1, "JOB_TYPE") = jobType;
    //alert('[JOB_TYPE]'+dts_Isu.NameValue(1, "JOB_TYPE") );


    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

    dts_Isu.setCellData(1, "ISUR_CD", $c.stf.getObjectValue(txb_ISUR_CD));
    dts_Isu.setCellData(1, "LIST_BZ_TP_CD", scwin.fn_getListBzTpCd());
    dts_Isu.setCellData(1, "PREFSTK_TP_CD", scwin.fn_getCheckboxNprefStk(chk_PREFSTK_TP_CD, $c.stf.getObjectValue(cmb_STKCERT_KIND_CD)));
    dts_Isu.setCellData(1, "INDEFINPD_YN", scwin.fn_getCheckboxData(chk_INDEFINPD_YN));
    dts_Isu.setCellData(1, "PARTCTP_YN", scwin.fn_getCheckboxData(chk_PARTCTP_YN));
    dts_Isu.setCellData(1, "ACCTP_YN", scwin.fn_getCheckboxData(chk_ACCTP_YN));
    dts_Isu.setCellData(1, "NDIVTM_VOTERGHT_YN", scwin.fn_getCheckboxData(chk_NDIVTM_VOTERGHT_YN));
    dts_Isu.setCellData(1, "NEWSTK_REL_LAWST_YN", scwin.fn_getCheckboxData(chk_NEWSTK_REL_LAWST_YN)); /*ORG SRC: dts_Isu.NameString(1, "BACKLIST_YN") = (fn_getCheckboxData(chk_BACKLIST_YN) == "Y" ? "Y" : '');*/ X = (scwin.fn_getCheckboxData(chk_BACKLIST_YN) == "Y" ? "Y" : ''); /*ORG SRC: dts_Isu.NameString(1, "NPARVALSTK_YN") = (fn_getCheckboxData(chk_NPARVALSTK_YN) == "Y" ? "Y" : '');*/ X = (scwin.fn_getCheckboxData(chk_NPARVALSTK_YN) == "Y" ? "Y" : '');
    dts_BackList.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=STKCERT_ISU_BACKLIST_INOUT";
    dts_BackList.reset();
    dts_BackList.insertRow();

    /*2010.03.05 우회상장 시 우회상장일도 같이 입력 */
    /*2010.07.16 우회상장 시 주식발행코드 입력 */
    if (chk_BACKLIST_YN.checked) {
        dts_BackList.setCellData(1, "ISUR_CD", dts_Isu.getCellData(1, "ISUR_CD"));
        dts_BackList.setCellData(1, "BZ_PROCS_NO", dts_Isu.getCellData(1, "BZ_PROCS_NO"));
        dts_BackList.setCellData(1, "BACKLIST_DD", dts_Isu.getCellData(1, "LIST_DD"));
        dts_BackList.setCellData(1, "BACKLIST_DESIGN_YN", "Y");
        dts_BackList.setCellData(1, "STK_ISU_RSN_CD", dts_Isu.getCellData(1, "STK_ISU_RSN_CD"));
    } else {
        if (dts_BackList.getTotalRow() > 0) {
            $c.cp.removeRow(dts_BackList, 1);
        }
    }

    //20081017 코스닥이고 발행사유가 이익소각이면 발행일자는 ~ 셋팅된다.
    /* 모델변경으로 제외(not null -> null) 2009.03.31
		if (getObjectValue(cmb_STK_ISU_RSN_CD) == "626"){
			if (dts_Isu.NameString(1, "ISU_DD") == ""){
dts_Isu.setNameString(1, "ISU_DD","~") ;
			}
		}
		*/

    for (i = 1; i <= dts_IsuDtl.getTotalRow(); i++) {
        dts_IsuDtl.setCellData(i, "BZ_PROCS_NO", dts_Isu.getCellData(1, "BZ_PROCS_NO"));
        dts_IsuDtl.setCellData(i, "SEQ", i);
        //dts_IsuDtl.NameValue(i, "JOB_TYPE") = TR_JOB_INSERT; //delete 후 insert 한다.

    }
    for (i = 1; i <= dts_PRTDEPO.getTotalRow(); i++) {
        dts_PRTDEPO.setCellData(i, "BZ_PROCS_NO", dts_Isu.getCellData(1, "BZ_PROCS_NO"));
        dts_PRTDEPO.setCellData(i, "SEQ", i); //저장하기 위해 이벤트를 발생시킨다.
        //dts_IsuDtl.NameValue(i, "JOB_TYPE") = TR_JOB_INSERT; //delete 후 insert 한다.

    }
    var vScrenProcTpCd;
    if (scwin.TR_JOB == "I") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_02;
    } else if (scwin.TR_JOB == "U") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
    } else if (scwin.TR_JOB == "D") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_04;
    }
    trs_Save.Action = $c.lc.fn_encodeNSession("/Listing.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcTpCd + "&method=saveIsuIssChgList");
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput_1=dts_Isu, I:pInput_2=dts_IsuDtl, I:pInput_3=dts_PRTDEPO, I:pInput_4=dts_BackList)";
    trs_Save.Parameters = "TRS_IDX=" + trsIdx + ",ACPT_NO=" + scwin.gAcptNo + ",BYACPTNO_SEQ=" + scwin.gAcptSeq + ",BZ_PROCS_NO=" + scwin.vBzProcsNo + ",COUNT=4" + ",GUBUN_CD=" + $c.stf.getObjectValue(cmb_LIST_METHD_TP_CD) + ",LIST_BZ_TP_CD=" + scwin.fn_getListBzTpCd() + ",LD_MKT_TP_CD=" + js_market + ",ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD) + ",FORM_CD=" + scwin.formCd + ",STK_ISU_RSN_CD=" + $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) + ",LIST_DD=" + $c.stf.getObjectValue(edt_LIST_DD) + ",DIV_IDX[0]=" + DIV_IDX_ISS_STK_HIST + ",DIV_IDX[1]=" + DIV_IDX_ISS_DTL_STK_HIST + ",DIV_IDX[2]=" + DIV_IDX_ISS_PRTDEPO_STK_HIST + ",DIV_IDX[3]=" + DIV_IDX_ISS_STK_BACK_LIST;
    trs_Save.Post();
};
