scwin.fn_isuDtlDtlAdd = function() {
    if ($c.stf.getObjectValue(edt_INDVDL_ISU_RND) == "") {
        $c.win.alert("[개별발행회차]를 입력하세요.");
        edt_INDVDL_ISU_RND.focus();
        return;
    }
    if ($c.stf.getObjectValue(edt_INDVDL_ISU_DD) == "") {
        $c.win.alert("[개별발행일]를 입력하세요.");
        edt_INDVDL_ISU_DD.focus();
        return;
    }
    if ($c.stf.getObjectValue(edt_INDVDL_ISU_PRC) == "") {
        //alert("[개별발행가]를 입력하세요.");edt_INDVDL_ISU_PRC.focus();return;

    }
    if ($c.stf.getObjectValue(edt_INDVDL_INCDEC_LIST_SHRS) == "") {
        $c.win.alert("[개별증감" + scwin.visuShrsLabelNm + "수]를 입력하세요.");
        edt_INDVDL_INCDEC_LIST_SHRS.focus();
        return;
    }
    var vRow = "";
    if (scwin.vIsuDtlRowPosition != "") {
        vRow = scwin.vIsuDtlRowPosition;
    } else {
        dts_IsuDtl.insertRow();
        vRow = dts_IsuDtl.getTotalRow();
    }

    //alert('[ getObjectValue(edt_INDVDL_ISU_PRC)]'+ getObjectValue(edt_INDVDL_ISU_PRC));
    //alert('[ getObjectValue(edt_INDVDL_INCDEC_LIST_SHRS)]'+ getObjectValue(edt_INDVDL_INCDEC_LIST_SHRS));
    dts_IsuDtl.setCellData(vRow, "ISU_RND", $c.stf.getObjectValue(edt_INDVDL_ISU_RND));
    dts_IsuDtl.setCellData(vRow, "ISU_PRC", $c.stf.getObjectValue(edt_INDVDL_ISU_PRC));
    dts_IsuDtl.setCellData(vRow, "ISU_SHRS", $c.stf.getObjectValue(edt_INDVDL_INCDEC_LIST_SHRS));
    dts_IsuDtl.setCellData(vRow, "ISU_DD", $c.stf.getObjectValue(edt_INDVDL_ISU_DD));
    dts_IsuDtl.setCellData(vRow, "PER1STK_CAP", $c.stf.getObjectValue(edt_INDVDL_PER1STK_CAP));
    dts_IsuDtl.setCellData(vRow, "CORPBND_ISU_RND", $c.stf.getObjectValue(edt_CORPBND_ISU_RND));
    if (dts_IsuDtl.getCellData(vRow, "PER1STK_CAP") > 0) {
        dts_IsuDtl.setCellData(vRow, "NPARVALSTK_YN", "Y");
    }
    scwin.fn_isuDtlDtlEvent();
};
scwin.fn_isuDtlDtlDel = function() {
    if (dts_IsuDtl.getTotalRow() == 0) {
        $c.win.alert("목록에서 [대상]을 선택하세요.");
        return;
    }
    $c.cp.removeRow(dts_IsuDtl, dts_IsuDtl.getRowPosition());
    scwin.fn_isuDtlDtlEvent();
};
scwin.fn_isuDtlDtlEvent = function() {
    $c.stf.setObjectValue(edt_INDVDL_ISU_RND, '');
    $c.stf.setObjectValue(edt_INDVDL_ISU_PRC, '');
    $c.stf.setObjectValue(edt_INDVDL_INCDEC_LIST_SHRS, '');
    $c.stf.setObjectValue(edt_INDVDL_ISU_DD, '');
    $c.stf.setObjectValue(edt_INDVDL_PER1STK_CAP, '');
    $c.stf.setObjectValue(edt_CORPBND_ISU_RND, '');
    scwin.fn_IsuPrcCalcuate();
    scwin.fn_IsuShrsCalcuate();
    scwin.vIsuDtlRowPosition = ""; //초기화

};
scwin.fn_IsuPrcCalcuate = function() {
    var vIsuPrcSum = 0;
    var vIsuRnd = "";
    var vIsuDd = "";
    try {
        if (dts_IsuDtl.getTotalRow() > 0) {
            vIsuPrcSum = eval(parseFloat(dts_IsuDtl.getCellData(1, "ISU_PRC")));
            vIsuRnd = dts_IsuDtl.getCellData(1, "ISU_RND");
            vIsuDd = dts_IsuDtl.getCellData(1, "ISU_DD");
            if (vIsuRnd == "") {
                vIsuRnd = $c.stf.getObjectValue(edt_ISU_RND);
            }
        }
    } catch (err) {
        $c.win.alert("[개별발행가 계산중  오류]" + err);
    }
    $c.stf.setObjectValue(edt_ISU_PRC, vIsuPrcSum);
    $c.stf.setObjectValue(edt_ISU_RND, vIsuRnd);
    $c.stf.setObjectValue(edt_ISU_DD, vIsuDd);
};
scwin.fn_IsuShrsCalcuate = function() {
    var vIsuShrsSum = 0;
    try {
        for (i = 1; i <= dts_IsuDtl.getTotalRow(); i++) {
            vIsuShrsSum += eval(parseInt(dts_IsuDtl.getCellData(i, "ISU_SHRS")));
        }
    } catch (err) {
        $c.win.alert("[개별증감" + scwin.visuShrsLabelNm + "수 합산처리 중  오류]" + err);
    }
    $c.stf.setObjectValue(edt_ISU_SHRS, vIsuShrsSum);
    scwin.calcuAccIsuShrs();
    scwin.calcusuCap();
    scwin.calcuAccIsuCap();
};
scwin.calcuAccIsuShrs = function() {
    try {
        var vsum = eval(parseInt($c.stf.getObjectValue(edt_BF_ACC_ISU_SHRS))) + eval(parseInt($c.stf.getObjectValue(edt_ISU_SHRS)));
        //alert( "[vsum]"+vsum);
        $c.stf.setObjectValue(edt_ACC_ISU_SHRS, vsum);
    } catch (err) {
        $c.win.alert("[변경후 상장증권수 계산 중 오류]" + err);
    }
};
scwin.calcusuCap = function() {
    if (scwin.vSecugrpID == SECUGRP_ID_DR) {
        $c.stf.setObjectValue(edt_ISU_CAP, '');
    } else {
        try {
            var vRsnCd = $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD);
            var vsum = 0;
            if (vRsnCd == '118' || //이익소각
                vRsnCd == '160' || //상호변경
                vRsnCd == '170' || //액면병합
                vRsnCd == '171' || //액면분할
                vRsnCd == '177') {
                //주식소각
                vsum = 0; //유가

            } else if (vRsnCd == '626' || //이익소각
                vRsnCd == '643' || //상호변경
                vRsnCd == '640' || //액면병합
                vRsnCd == '641' || //액면분할
                vRsnCd == '650') {
                //주식소각 
                vsum = 0; //코스닥

            } else {
                if (scwin.vSecugrpID == SECUGRP_ID_MF || scwin.vSecugrpID == SECUGRP_ID_IF) {
                    vsum = eval(parseFloat($c.stf.getObjectValue(edt_ISU_PRC))) * eval(parseFloat($c.stf.getObjectValue(edt_ISU_SHRS)));
                } else {
                    if ($c.stf.getObjectValue(chk_NPARVALSTK_YN) == "Y") {
                        vsum = eval(parseFloat($c.stf.getObjectValue(edt_PER1STK_CAP))) * eval(parseFloat($c.stf.getObjectValue(edt_ISU_SHRS)));
                    } else {
                        vsum = eval(parseFloat($c.stf.getObjectValue(edt_PARVAL))) * eval(parseFloat($c.stf.getObjectValue(edt_ISU_SHRS)));
                    }
                }
            }
            //alert( "[증감자본금 vsum]"+vsum);
            $c.stf.setObjectValue(edt_ISU_CAP, vsum);
        } catch (err) {
            $c.win.alert("[증감 상장자본금 계산 중  오류]" + err);
        }
    }
};
scwin.calcuAccIsuCap = function() {
    if (scwin.vSecugrpID == SECUGRP_ID_DR) {
        $c.stf.setObjectValue(edt_ACC_ISU_CAP, '');
    } else {
        try {
            var vRsnCd = $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD);
            var vsum = '';
            if (vRsnCd == '118' || //이익소각
                vRsnCd == '160' || //상호변경
                vRsnCd == '170' || //액면병합
                vRsnCd == '177' || //주식소각
                vRsnCd == '171') {
                //액면분할
                vsum = $c.stf.getObjectValue(edt_BF_ACC_ISU_CAP); //유가
                $c.stf.setObjectValue(edt_ISU_CAP, 0); //유가

            } else if (vRsnCd == '626' || //이익소각
                vRsnCd == '643' || //상호변경
                vRsnCd == '640' || //액면병합
                vRsnCd == '650' || //주식소각
                vRsnCd == '641') {
                //액면분할
                vsum = $c.stf.getObjectValue(edt_BF_ACC_ISU_CAP); //코스닥
                $c.stf.setObjectValue(edt_ISU_CAP, 0); //코스닥

            } else {
                scwin.calcusuCap();
                vsum = eval(parseFloat($c.stf.getObjectValue(edt_BF_ACC_ISU_CAP))) + eval(parseFloat($c.stf.getObjectValue(edt_ISU_CAP)));
            }
            $c.stf.setObjectValue(edt_ACC_ISU_CAP, vsum);
        } catch (err) {
            $c.win.alert("[변경후 상장자본금 계산 중  오류]" + err);
        }
    }
};
