    }
};





/**
 * 인쇄할 내용을 불러온다.
 * reportCd = 0 : 상호변경
 *                  1 : 보호예수
 *                  2 : 주식발행내역
 *                  3 : 주식발행내역상세
 */
scwin.fn_report_read_sync = function(vBzProcsKey, reportCd) {
    var url = "/Listing.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_05 + "&method=searchIssReport" + "&DIV_IDX=" + reportCd + "&BZ_PROCS_NO=" + vBzProcsKey;
    dts_Report.DataID = encodeURI(url);
    dts_Report.Reset();
};
scwin.fn_print = function() {
    var vReportCd = $c.stf.getObjectValue(cmb_REPORT_CD); //1^인쇄,2^보호예수인쇄,3^통합인쇄
    var vBzProcsKey = scwin.vBzProcsNo;
    if (vReportCd == "1") {
        var isuRsnCd = $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD);
        if (isuRsnCd == '643') {
            //상호변경(코)
            scwin.fn_print_1_1(vBzProcsKey);
        } else {
            scwin.fn_print_1_2(vBzProcsKey, 'N');
        }
    } else if (vReportCd == "2") {
        scwin.fn_print_2(vBzProcsKey); //우리기술...

    } else if (vReportCd == "3") {
        var url = "/Listing.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_05 + "&method=searchIssReport" + "&DIV_IDX=" + DIV_IDX_ISS_TOTAL_REPORT + "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD) + "&LIST_DD=" + $c.stf.getObjectValue(edt_LIST_DD) + "&GUBUN_CD=" + $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD);
        dts_Report_4.DataID = encodeURI(url);
        dts_Report_4.Reset();
        var pValue = "";
        var k = 0;
        for (var i = 1; i <= dts_Report_4.getTotalRow(); i++) {
            if (k == 0) {
                pValue = dts_Report_4.getCellData(i, "BZ_PROCS_NO");
            } else {
                pValue = pValue + "," + dts_Report_4.getCellData(i, "BZ_PROCS_NO");
            }
            k++;
        }
        vBzProcsKey = pValue;
        scwin.fn_print_1_2(vBzProcsKey, 'Y');
    }
};



/**********************************************
 * 설명 : 상호변경  인쇄한다. (Convert PDF)
 ***********************************************/
scwin.fn_print_1_1 = function(vBzProcsKey) {
