            gChg1PrestkShrs = "";
            gChg2PrestkShrs = "";
            gChg3PrestkShrs = "";
            gChgDivDD = "";
            gChgParVal = "";
            gChgIsuCap = "";
            gChgIsuPrc = "";
            for (var i = 1; i <= dts_Report.getTotalRow(); i++) {
