scwin.fn_setPrestkEndDDEvent = function() {
    if (chk_INDEFINPD_YN.checked) {
        $c.win.alert("이미[무기한여부]가 선택되었습니다.\n\n만료일을 입력하시려면 무기한여부선택을 해제하시고 \n존속기한을 선택하십시요.");
        return;
    }
    if ($c.stf.getObjectValue(edt_PREFSTK_ISU_DD) == "") {
        $c.win.alert("[우선주발행일]을 입력하세요.");
        edt_PREFSTK_ISU_DD.focus();
        return;
    }
    var vTgt;
    var vSrc = $c.stf.getObjectValue(edt_PREFSTK_ISU_DD);
    vTgt = $c.ut.cGetPlusYear(vSrc, $c.stf.getObjectValue(edt_PREFSTK_CONTIN_DEADLINE_YYS));
    $c.stf.setObjectValue(edt_PREFSTK_END_DD, vTgt);
    vSrc = $c.stf.getObjectValue(edt_PREFSTK_END_DD);
    vTgt = $c.ut.cGetPlusMonth(vSrc.substring(0, 4), vSrc.substring(4, 6), vSrc.substring(6, 8), $c.stf.getObjectValue(edt_PREFSTK_CONTIN_DEADLINE_MM));
    $c.stf.setObjectValue(edt_PREFSTK_END_DD, vTgt);
    vSrc = $c.stf.getObjectValue(edt_PREFSTK_END_DD);
    vTgt = $c.ut.cGetPlusDate2(vSrc, $c.stf.getObjectValue(edt_PREFSTK_CONTIN_DEADLINE_DYS));
    $c.stf.setObjectValue(edt_PREFSTK_END_DD, vTgt);
};
scwin.fn_setNPARVALSTK_YNEvent = function() {
    if (chk_NPARVALSTK_YN.checked) {
        edt_PARVAL.setReadOnly(true);
        edt_PARVAL.ReadOnlyBackColor = '#b9d4f7';
        $c.stf.setObjectValue(edt_PARVAL, '0');
        edt_PER1STK_CAP.setReadOnly(false);
        edt_PER1STK_CAP.ReadOnlyBackColor = '#ffffff';
    } else {
        edt_PARVAL.setReadOnly(false);
        edt_PARVAL.ReadOnlyBackColor = '#ffffff';
        edt_PER1STK_CAP.setReadOnly(true);
        edt_PER1STK_CAP.ReadOnlyBackColor = '#b9d4f7';
        $c.stf.setObjectValue(edt_PER1STK_CAP, '');
    }
};
scwin.fn_smsSend = async function() {
    var vMainFormCd;
    var vListMthTpCd = $c.stf.getObjectValue(cmb_LIST_METHD_TP_CD);
    if (vListMthTpCd == LIST_METHD_TP_CD_3) {
        //변경상장
        if (js_market == "2") {
            vMainFormCd = "70933";
        } else {
            vMainFormCd = "33033";
        }
    } else {
        if (js_market == "2") {
            vMainFormCd = "70932";
        } else {
            vMainFormCd = "33032";
        }
    }
    var url = "/lstproc/ULDSTF05014.gfm?ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD) + "&ACPT_NO=" + scwin.gAcptNoListFee + "&FORM_CD=" + vMainFormCd;
    await $c.frame.CreateDialogFrame("COS_LISTFEE", url, "상장수수료발송", 400, 300, 410, 200, "window");
    scwin.fn_listFee();
};
scwin.fn_listFee = function() {
    url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=LIST_FEE_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.lstmgt.select.listfee.smssend.dtl" + "&{P}param01=" + scwin.gAcptNoListFee; //  접수번호


    dts_listfee.DataID = encodeURI(url);
    dts_listfee.reset();
    var fee = dts_listfee.getCellData(1, "LIST_COMMON_SUM");
    var feeEx = dts_listfee.getCellData(1, "EXMPT_YN");
    edt_listFee.setValue(fee);
    if (feeEx == "Y") {
        chk_feeExmpt.setValue(1);
    } else {
        chk_feeExmpt.setValue(0);
    }
};





