/**********************************************
 * ASIS rexpert-bak 2018-04-03
 * 설명 : 변경상장신청내역  인쇄한다.
 * totalYn : 통합인쇄 여부
 * 배당기산일은 변경전/후를 추가배당일과 동일하게 함-현업요청
 ***********************************************/
scwin.fn_print_1_2_old = function(vBzProcsKey, totalYn) {

    //dts_Print.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    //껍데기만 만들고 사용자필드를 사용함
    dts_Print.insertRow();
    scwin.fn_report_read_sync(vBzProcsKey, DIV_IDX_ISS_REPORT);
    var userParam = [{
        uid: "ISU_INFO",
        unm: dts_Report.getCellData(1, "COM_NM") + " / " + dts_Report.getCellData(1, "REP_ISU_SRT_CD")
    }, {
        uid: "STK_ISU_RSN_NM",
        unm: dts_Report.getCellData(1, "STK_ISU_RSN_NM")
    }, {
        uid: "BF_CMSTK_SHRS",
        unm: dts_Report.getCellData(1, "BF_CMSTK_SHRS")
    }, {
        uid: "BF_1PREFSTK_SHRS",
        unm: dts_Report.getCellData(1, "BF_1PREFSTK_SHRS")
    }, {
        uid: "BF_2PREFSTK_SHRS",
        unm: dts_Report.getCellData(1, "BF_2PREFSTK_SHRS")
    }, {
        uid: "BF_3PREFSTK_SHRS",
        unm: dts_Report.getCellData(1, "BF_3PREFSTK_SHRS")
    }, {
        uid: "BF_DIV_RECK_DD",
        unm: dts_Report.getCellData(1, "AF_DIV_RECK_DD")
    }, {
        uid: "BF_PARVAL",
        unm: dts_Report.getCellData(1, "BF_PARVAL")
    }, {
        uid: "BF_ISU_CAP",
        unm: dts_Report.getCellData(1, "BF_ISU_CAP")
    }, {
        uid: "AF_CMSTK_SHRS",
        unm: dts_Report.getCellData(1, "AF_CMSTK_SHRS")
    }, {
        uid: "AF_1PREFSTK_SHRS",
        unm: dts_Report.getCellData(1, "AF_1PREFSTK_SHRS")
    }, {
        uid: "AF_2PREFSTK_SHRS",
        unm: dts_Report.getCellData(1, "AF_2PREFSTK_SHRS")
    }, {
        uid: "AF_3PREFSTK_SHRS",
        unm: dts_Report.getCellData(1, "AF_3PREFSTK_SHRS")
    }, {
        uid: "AF_DIV_RECK_DD",
        unm: dts_Report.getCellData(1, "AF_DIV_RECK_DD")
    }, {
        uid: "AF_PARVAL",
        unm: dts_Report.getCellData(1, "AF_PARVAL")
    }, {
        uid: "AF_ISU_CAP",
        unm: dts_Report.getCellData(1, "AF_ISU_CAP")
    }, {
        uid: "APPROV_DD",
        unm: dts_Report.getCellData(1, "APPROV_DD")
    }, {
        uid: "ISS_INFO",
        unm: dts_Report.getCellData(1, "ISS_INFO")
    }, {
        uid: "RETISECU_DD",
        unm: dts_Report.getCellData(1, "RETISECU_DD")
    }, {
        uid: "LIST_DD",
        unm: dts_Report.getCellData(1, "LIST_DD")
    }, {
        uid: "CURR_ISO_CD",
        unm: dts_Report.getCellData(1, "CURR_ISO_CD")
    }];
    //dts_ReportIsuDtl.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    var gChgCmstkShrs = "";
    var gChg1PrestkShrs = "";
    var gChg2PrestkShrs = "";
    var gChg3PrestkShrs = "";
    var gChgDivDD = "";
    var gChgParVal = "";
    var gChgIsuCap = "";
    var gChgIsuPrc = "";


    //일단 변경상장을 포함하여 주식발행에서 넣는다.(추가상장인경우 주식발행상세에 데이타 없는경우도 있음)
    gChgCmstkShrs = $c.stf.addCommaMinus(dts_Report.getCellData(1, "CHG_CMSTK_SHRS"));
    gChg1PrestkShrs = $c.stf.addCommaMinus(dts_Report.getCellData(1, "CHG_1PREFSTK_SHRS"));
    gChg2PrestkShrs = $c.stf.addCommaMinus(dts_Report.getCellData(1, "CHG_2PREFSTK_SHRS"));
    gChg3PrestkShrs = $c.stf.addCommaMinus(dts_Report.getCellData(1, "CHG_3PREFSTK_SHRS"));
    gChgIsuCap = dts_Report.getCellData(1, "CHG_ISU_CAP");
    gChgIsuPrc = $c.stf.addCommaMinus(dts_Report.getCellData(1, "CHG_ISU_PRC"));
    gChgDivDD = $c.stf.FormatDateEx(dts_Report.getCellData(1, "CHG_DIV_RECK_DD"));
    gChgParVal = dts_Report.getCellData(1, "CHG_PARVAL");
    if ($c.stf.getObjectValue(cmb_LIST_METHD_TP_CD) != LIST_METHD_TP_CD_3) {
        // 변경상장

        scwin.fn_report_read_sync(vBzProcsKey, DIV_IDX_ISS_DTL_REPORT); //주식발행상세

        if (dts_Report.getTotalRow() > 0) {
            //과거자료는 주식발행상세에 정보가 없어서 주식발행에서 넣는다.
            //초기화..
            gChgCmstkShrs = "";
            gChg1PrestkShrs = "";
            gChg2PrestkShrs = "";
            gChg3PrestkShrs = "";
            gChgDivDD = "";
            gChgParVal = "";
            gChgIsuCap = "";
            gChgIsuPrc = "";
            for (var i = 1; i <= dts_Report.getTotalRow(); i++) {
                gChgCmstkShrs += $c.stf.addCommaMinus(dts_Report.getCellData(i, "CHG_CMSTK_SHRS")) + "\r\n";
                gChg1PrestkShrs += $c.stf.addCommaMinus(dts_Report.getCellData(i, "CHG_1PREFSTK_SHRS")) + "\r\n";
                gChg2PrestkShrs += $c.stf.addCommaMinus(dts_Report.getCellData(i, "CHG_2PREFSTK_SHRS")) + "\r\n";
                gChg3PrestkShrs += $c.stf.addCommaMinus(dts_Report.getCellData(i, "CHG_3PREFSTK_SHRS")) + "\r\n";
                gChgIsuCap += $c.stf.addCommaMinus(dts_Report.getCellData(i, "CHG_ISU_CAP")) + "\r\n";
                gChgIsuPrc += $c.stf.addCommaMinus(dts_Report.getCellData(i, "CHG_ISU_PRC")) + "\r\n";
                if (totalYn == 'Y') {
                    gChgDivDD += $c.stf.FormatDateEx(dts_Report.getCellData(1, "CHG_DIV_RECK_DD")) + "\r\n";
                    gChgParVal += dts_Report.getCellData(1, "CHG_PARVAL") + "\r\n";
                }
            }
            if (totalYn == 'N') {
                gChgDivDD = $c.stf.FormatDateEx(dts_Report.getCellData(1, "CHG_DIV_RECK_DD"));
                gChgParVal = dts_Report.getCellData(1, "CHG_PARVAL");
            }
        }
    }
    dts_ReportIsuDtl.insertRow();
    dts_ReportIsuDtl.setCellData(1, "CHG_CMSTK_SHRS", gChgCmstkShrs);
    dts_ReportIsuDtl.setCellData(1, "CHG_1PREFSTK_SHRS", gChg1PrestkShrs);
    dts_ReportIsuDtl.setCellData(1, "CHG_2PREFSTK_SHRS", gChg2PrestkShrs);
    dts_ReportIsuDtl.setCellData(1, "CHG_3PREFSTK_SHRS", gChg3PrestkShrs);
    dts_ReportIsuDtl.setCellData(1, "CHG_DIV_RECK_DD", gChgDivDD);
    dts_ReportIsuDtl.setCellData(1, "CHG_PARVAL", gChgParVal);
    dts_ReportIsuDtl.setCellData(1, "CHG_ISU_CAP", gChgIsuCap);
    dts_ReportIsuDtl.setCellData(1, "CHG_ISU_PRC", gChgIsuPrc);
    scwin.fn_report_read_sync(vBzProcsKey, DIV_IDX_PRTDEPO_REPORT);
    //dts_Report2.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    for (var i = 1; i <= dts_Report.getTotalRow(); i++) {
        dts_Report2.insertRow();
        dts_Report2.setCellData(i, "PRTDEPO_RSN_NM", dts_Report.getCellData(i, "PRTDEPO_RSN_NM"));
        dts_Report2.setCellData(i, "PRTDEPO_SHRS", dts_Report.getCellData(i, "PRTDEPO_SHRS"));
        dts_Report2.setCellData(i, "STKCERT_KIND_NM", dts_Report.getCellData(i, "STKCERT_KIND_NM"));
        dts_Report2.setCellData(i, "PRTDEPO_TERM_DD", dts_Report.getCellData(i, "PRTDEPO_TERM_DD"));
    }
    var testDateSet = rex_gfGetGauceCsvStr(dts_Print, dts_ReportIsuDtl, dts_Report2);


    //Rexpert리포트 파일명
    //var rex_rptname = "test/sample4";
    var rex_rptname = "RLDSTF00007";

    //Rexpert 미리보기 호출
    $c.rpt.fn_open_report(testDateSet, rex_rptname, userParam);
};


