scwin.dts_Isu_OnLoadCompleted = function(rowcount) {
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    if (scwin.vBzProcsNo == "") {
        buttonSet.setInsertStatus();
        scwin.fn_initForm('C');
    } else {
        scwin.fn_initForm('X');
        if (vCurDate <= $c.stf.getObjectValue(edt_LIST_DD)) {
            buttonSet.setUpdateStatus();
        } else {
            if (dts_Isu.getCellData(1, "DISCLS_YN") == 'Y') {
                buttonSet.setErrorStatus(); //disable 시킨다.

            } else {
                buttonSet.setUpdateStatus();
            }
        }
    }
    if (scwin.gAcptNo != "" && scwin.vBzProcsNo == "") {
        btn_RecvIsuDel.src = "../img/btn_RcvdocDel.gif";
        btn_RecvIsuDel.setDisabled(false);
    } else {
        btn_RecvIsuDel.src = "../img/btn_RcvdocDel_d.gif";
        btn_RecvIsuDel.setDisabled(true);
    }
    scwin.setTabPanel();
};
scwin.dts_IsuDtl_OnLoadCompleted = function(rowcount) {
    if (scwin.gAcptNo != "" && scwin.vBzProcsNo == "") {
        var vListMthTpCd = dts_Isu.getCellData(1, "LIST_METHD_TP_CD");
        if (vListMthTpCd == LIST_METHD_TP_CD_1 || vListMthTpCd == LIST_METHD_TP_CD_2) {
            //주식발행사유로 체크하지말고 건수로 하자..
            if (dts_IsuDtl.getTotalRow() == 0) {
                dts_IsuDtl.insertRow();
                dts_IsuDtl.setCellData(1, "ISU_RND", dts_Isu.getCellData(1, "ISU_RND"));
                dts_IsuDtl.setCellData(1, "ISU_PRC", dts_Isu.getCellData(1, "ISU_PRC"));
                dts_IsuDtl.setCellData(1, "ISU_SHRS", dts_Isu.getCellData(1, "ISU_SHRS"));
                dts_IsuDtl.setCellData(1, "ISU_DD", dts_Isu.getCellData(1, "ISU_DD"));
                dts_IsuDtl.setCellData(1, "PER1STK_CAP", dts_Isu.getCellData(1, "PER1STK_CAP"));
            } else {
                for (j = 1; j <= dts_IsuDtl.getTotalRow(); j++) {
                    dts_IsuDtl.setCellData(j, "ISU_RND", dts_Isu.getCellData(1, "ISU_RND"));
                }
            }

            /*
            var vRsnCd = getObjectValue(cmb_STK_ISU_RSN_CD);
            var gDtl = 'Y';
            alert('[vRsnCd]'+vRsnCd);
            if (vRsnCd == '612' ||
