scwin.cmb_STK_ISU_RSN_CD_OnSelChange = function() {
    if (!btn_RecvIsuDel.getDisabled()) {
        if (js_market == '1' && scwin.vPageTYp == "2" && $c.stf.getObjectValue(cmb_LIST_METHD_TP_CD) == LIST_METHD_TP_CD_3) {
            // 유가, 변경상장
            if ($c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) != "" &&
                $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) != "170" &&
                $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) != "171" &&
                $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) != "172" &&
                $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) != "173" &&
                $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) != "174" &&
                $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) != "177" &&
                $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) != "118" &&
                $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) != "160" &&
                $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) != "161" &&
                $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) != "180" &&
                $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) != "162" &&
                $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) != "163" &&
                $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) != "175" &&
                $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) != "176") {
                if (!confirm("변경상장에서 안내문 형식이 정의되지 않은 주식 발행사유 입니다. \n그래도 선택한 주식발행사유를 입력하시겠습니까?")) {
                    $c.stf.setObjectValue(cmb_STK_ISU_RSN_CD, '');
