scwin.cmb_LIST_METHD_TP_CD_OnSelChange = function() {
    if ($c.stf.getObjectValue(cmb_LIST_METHD_TP_CD) == "1") {
        var vListMthTpCd = $c.stf.getObjectValue(cmb_LIST_METHD_TP_CD);
        if (scwin.vPageTYp == '1') {
            if (vListMthTpCd != LIST_METHD_TP_CD_2) {
                $c.win.alert("이화면에서는  상장방식을 [추가상장]만 선택할 수 있습니다.");
                $c.stf.setObjectValue(cmb_LIST_METHD_TP_CD, '2');
                cmb_LIST_METHD_TP_CD.focus();
                return false;
            }
        } else if (scwin.vPageTYp == '2') {
            if (vListMthTpCd != LIST_METHD_TP_CD_3) {
                $c.win.alert("이화면에서는  상장방식을 [변경상장]만 선택할 수 있습니다.");
                $c.stf.setObjectValue(cmb_LIST_METHD_TP_CD, '3');
                cmb_LIST_METHD_TP_CD.focus();
                return false;
            }
        }
    }
};
