scwin.gform_onload = async function() {
    var parentWin = scwin.fn_GetProvider();
    //var parentWin = frame.Provider("../");

    scwin.vBzProcsNo = parentWin.clickBzProcsNo;
    scwin.vSecugrpID = parentWin.fr_SecuGrpId;
    scwin.vPageTYp = parentWin.scwin.vPageTYp;
    scwin.vSPOT_ISU_TRD_MKT_TP_CD = parentWin.scwin.vSPOT_ISU_TRD_MKT_TP_CD;
    $c.stf.setObjectValue(txb_ISUR_CD, $c.stf.getObjectValue(parentWin.txb_ISUR_CD));
    $c.stf.setObjectValue(txb_COM_NM, $c.stf.getObjectValue(parentWin.txb_COM_NM));
    scwin.gAcptNo = parentWin.scwin.gAcptNo;
    scwin.gAcptSeq = (parentWin.scwin.gAcptSeq == "" ? 0 : parentWin.scwin.gAcptSeq);

    //상장수수료를 위한 접수번호
    scwin.gAcptNoListFee = parentWin.scwin.gAcptNoListFee;
    scwin.setObjectState();

    //resizeToWin() ;
    scwin.fn_searchCode();
    scwin.fn_SetComboCode();
    $c.cm.PanelToGroupBox(panel_Item);
    scwin.fn_setPanelPREFSTK(false); //일단 false;
    scwin.fn_setPREFSTKItem(false); //일단 false;

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    buttonSet.setSaveInfo(btn_Save, fn_save); // 저장
    buttonSet.setUpdateInfo(btn_Update, fn_update); // 수정
    buttonSet.setDeleteInfo(btn_Delete, fn_delete); // 삭제

    edt_APPROV_DD.setValue($c.ut.cGetToday("yyyymmdd"));
    if (scwin.vBzProcsNo != "") {
        cmb_LIST_METHD_TP_CD.CBData = "1^신주상장,2^추가상장,3^변경상장,4^신규상장,5^재상장";
        scwin.fn_read_sync();
    } else {
        if (scwin.gAcptNo != undefined && scwin.gAcptNo != "") {
            scwin.fn_extr_read_sync();
            scwin.fn_SetHeader('N');
        } else {
            scwin.fn_SetHeader('Y');
        }
        var vListMthTpCd;
        if (scwin.vPageTYp == '1') {
            //vListMthTpCd =  "1^신주상장,2^추가상장" ;
            vListMthTpCd = "2^추가상장";
            cmb_LIST_METHD_TP_CD.CBData = vListMthTpCd;
            //cmb_LIST_METHD_TP_CD.Index = 1;
            cmb_LIST_METHD_TP_CD.setSelectedIndex(0);
            scwin.fn_nprefstk_read_sync(txb_ISU_CD.getValue());
        } else if (scwin.vPageTYp == '2') {
            vListMthTpCd = "3^변경상장";
            cmb_LIST_METHD_TP_CD.CBData = vListMthTpCd;
            cmb_LIST_METHD_TP_CD.setSelectedIndex(0);
        }
    }
    scwin.setTabPanel();
    buttonSet.setButtonDepCd(dts_ByCorpDepCd, $c.stf.getObjectValue(txb_ISUR_CD), js_dep_cd);
    if ($c.stf.getObjectValue(cmb_STKCERT_KIND_CD) != "KDR" && $c.stf.getObjectValue(cmb_STKCERT_KIND_CD).substring(0, 1) == "K") {
        scwin.fn_setNPARVALSTK(true);
    } else {
        scwin.fn_setNPARVALSTK(false);
    }
    //주식발행사유가 스톡옵션행사(117)(유), 주식매수선택권행사(614)(코) 인경우 주식매수선택권 의무보유 관리 팝업창 호출
    var parentSrc = parentWin.scwin.vScrenID;
    if ((parentSrc == "ULDSTF05200.gfm" || parentSrc == "ULDSTF05255.gfm") && (scwin.vSecugrpID == "ST" || scwin.vSecugrpID == "DR" || scwin.vSecugrpID == "FS") &&
        ($c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) == "117" || $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD) == "614")) {
        scwin.vStkOptIsurCd = $c.stf.getObjectValue(txb_ISUR_CD);
        scwin.vStkOptComNm = $c.stf.getObjectValue(txb_COM_NM);
        await $c.frame.CreateDialogFrame("ULDSTF40003", "/lstmgt/ULDSTF40003.gfm", "주식매수선택권 의무보유 관리", 100, 100, 1300, 790, "window");
    }
};
